const Home = () => {

    let name = "Escape";
    function handleClick() {
        name = (name === "me") ? "Escape" : "me";
        console.log("Name changed to ", name)
    }
    return ( 
        <div className="home">
            <h2>HomePage</h2>
            <p>{"mario"}</p>
            <button onClick={handleClick}></button>
        </div>
     );
}
 
export default Home;
